CREATE TYPE CATEGORY_TYPE AS ENUM (
	'PARFUM',
	'COSMETICS',
	'HOME_FRAGRANCE'
);

CREATE TYPE ORDER_STATUS AS ENUM (
	'PENDING',
	'COMPLETED',
	'CANCELLED'
);

CREATE TYPE TARGET_AUDIENCE AS ENUM (
	'MEN',
	'WOMEN',
	'UNISEX'
);

CREATE TYPE TRANSACTION_TYPE AS ENUM (
	'ONLINE_ORDER',
	'IN_STORE_SALE'
);

CREATE TYPE USER_ROLE AS ENUM (
	'CLIENT',
	'CASHIER',
	'MANAGER'
);

CREATE TABLE IF NOT EXISTS "product" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL,
    "brand" VARCHAR(255) NOT NULL,
    "category_type" CATEGORY_TYPE NOT NULL,
    "target_audience" TARGET_AUDIENCE,
    "description" TEXT,
    "volume_ml" INTEGER NOT NULL,
    "price" NUMERIC(10,2) NOT NULL,
    "release_year" INTEGER NOT NULL,
    "current_stock" INTEGER NOT NULL DEFAULT 0,
    "is_available" BOOLEAN NOT NULL DEFAULT true,
    PRIMARY KEY("id")
    );

CREATE TABLE IF NOT EXISTS "price_history" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_id" BIGINT NOT NULL,
    "old_price" NUMERIC(10,2) NOT NULL,
    "new_price" NUMERIC(10,2) NOT NULL,
    "changed_at" TIMESTAMPTZ NOT NULL,
    PRIMARY KEY("id")
    );

CREATE TABLE IF NOT EXISTS "stock_supply" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_id" BIGINT NOT NULL,
    "supplier_name" VARCHAR(255) NOT NULL,
    "quantity_added" INTEGER NOT NULL,
    "supply_date" DATE NOT NULL,
    "purchase_price" NUMERIC(10,2) NOT NULL,
    PRIMARY KEY("id")
    );

CREATE TABLE IF NOT EXISTS "user_account" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "email" VARCHAR(255) NOT NULL UNIQUE,
    "password_hash" VARCHAR(255) NOT NULL,
    "first_name" VARCHAR(100) NOT NULL,
    "last_name" VARCHAR(100) NOT NULL,
    "phone" VARCHAR(25),
    "role" USER_ROLE NOT NULL,
    PRIMARY KEY("id")
    );

CREATE TABLE IF NOT EXISTS "sale_transaction" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "customer_id" BIGINT,
    "employee_id" BIGINT,
    "transaction_type" TRANSACTION_TYPE NOT NULL,
    "delivery_address_id" BIGINT,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "status" ORDER_STATUS NOT NULL,
    "total_price" NUMERIC(10,2) NOT NULL,
    PRIMARY KEY("id")
    );

CREATE TABLE IF NOT EXISTS "delivery_address" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" BIGINT NOT NULL,
    "street" VARCHAR(255) NOT NULL,
    "city" VARCHAR(100) NOT NULL,
    "postal_code" VARCHAR(20) NOT NULL,
    "country" VARCHAR(10) NOT NULL,
    PRIMARY KEY("id")
    );

CREATE TABLE IF NOT EXISTS "transaction_item" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_id" BIGINT NOT NULL,
    "transaction_id" BIGINT NOT NULL,
    "quantity" INTEGER NOT NULL,
    "unit_price" NUMERIC(10,2) NOT NULL,
    PRIMARY KEY("id")
    );

CREATE TABLE IF NOT EXISTS "fragrance_note" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL UNIQUE,
    PRIMARY KEY("id")
    );

CREATE TABLE IF NOT EXISTS "product_note" (
    "product_id" BIGINT NOT NULL,
    "note_id" INTEGER NOT NULL,
    PRIMARY KEY("product_id", "note_id")
    );

ALTER TABLE "price_history"
    ADD FOREIGN KEY("product_id") REFERENCES "product"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "stock_supply"
    ADD FOREIGN KEY("product_id") REFERENCES "product"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "sale_transaction"
    ADD FOREIGN KEY("customer_id") REFERENCES "user_account"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "sale_transaction"
    ADD FOREIGN KEY("employee_id") REFERENCES "user_account"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "delivery_address"
    ADD FOREIGN KEY("user_id") REFERENCES "user_account"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "sale_transaction"
    ADD FOREIGN KEY("delivery_address_id") REFERENCES "delivery_address"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "transaction_item"
    ADD FOREIGN KEY("product_id") REFERENCES "product"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "transaction_item"
    ADD FOREIGN KEY("transaction_id") REFERENCES "sale_transaction"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "product_note"
    ADD FOREIGN KEY("product_id") REFERENCES "product"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "product_note"
    ADD FOREIGN KEY("note_id") REFERENCES "fragrance_note"("id")
        ON UPDATE NO ACTION ON DELETE NO ACTION;